insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000001', 'Hendra Wijaya', 'hendra.wijaya82@example.com', null, 'commercial', 'Rp250 – 500 jt', 'Selamat siang, kami sedang mencari arsitek untuk coffee shop dua lantai di Jl. Gajah Mada, luas bangunan sekitar 180 m². Apakah studio menerima proyek di Pontianak kota? Kami ingin buka sebelum Lebaran.', 'closed', 'website', encode(sha256(convert_to('hendra.wijaya82@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-01-08 10:12+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000002', 'Wahyu Saputra', 'wahyu.saputra@example.com', null, 'commercial', 'Rp100 – 250 jt', 'Halo, kami ingin membuka cabang kedua kedai kami. Konsepnya kurang lebih sama dengan cabang pertama tapi lahannya lebih sempit. Bisa diskusi minggu ini?', 'closed', 'website', encode(sha256(convert_to('wahyu.saputra@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-01-05 19:40+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000003', 'Maria Susanti', 'maria.susanti@example.com', null, 'interior', 'Rp50 – 100 jt', 'Saya ingin renovasi interior dapur dan ruang makan rumah di Kota Baru. Kira-kira berapa lama proses desainnya dan apakah termasuk pengawasan?', 'closed', 'website', encode(sha256(convert_to('maria.susanti@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-02-03 08:55+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000004', 'Dimas Pratama', 'dimas.pratama@example.com', null, 'residential', 'Rp100 – 250 jt', 'Rumah peninggalan orang tua, dibangun tahun 1990-an, ingin direnovasi supaya lebih terang dan tidak lembap. Apakah bisa survei dulu sebelum penawaran?', 'contacted', 'website', encode(sha256(convert_to('dimas.pratama@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-03-11 21:15+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000005', 'Yuliana Effendi', 'yuliana.effendi@example.com', null, 'commercial', 'Rp250 – 500 jt', 'Kami ingin membuka cabang restoran di Singkawang. Butuh desain bangunan baru sekaligus interior. Mohon info paket dan jadwal kosong studio.', 'closed', 'website', encode(sha256(convert_to('yuliana.effendi@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-02-09 13:30+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000006', 'Kevin Gunawan', 'kevin.gunawan@example.com', null, 'residential', 'Rp500 jt – Rp1 M', 'Rencana bangun rumah tinggal 2 lantai di Sungai Raya Dalam, luas tanah 15 x 30. Ingin gaya tropis modern dengan banyak bukaan. Bisa minta portofolio rumah tinggal?', 'qualified', 'website', encode(sha256(convert_to('kevin.gunawan@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-04-14 07:48+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000007', 'Hartono Wijaya', 'hartono.wijaya@example.com', null, 'commercial', 'Di atas Rp1 M', 'Kami mengelola beberapa outlet F&B dan ada tiga lokasi baru tahun ini di luar Pontianak. Mohon dijadwalkan pertemuan untuk membahas paket beberapa proyek sekaligus.', 'closed', 'website', encode(sha256(convert_to('hartono.wijaya@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-03-28 16:05+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000008', 'Rahmat Hidayat', 'rahmat.hidayat@example.com', null, 'renovation', 'Rp50 – 100 jt', 'Ruko 3 lantai di Jl. Tanjungpura mau diubah lantai bawahnya jadi kafe kecil. Apakah studio menangani renovasi skala kecil?', 'contacted', 'website', encode(sha256(convert_to('rahmat.hidayat@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-05-19 11:22+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000009', 'Fransiska Ayu', 'fransiska.ayu@example.com', null, 'interior', 'Rp100 – 250 jt', 'Butuh desain interior klinik kecantikan sekitar 90 m², target buka akhir tahun. Apakah bisa sampai gambar kerja untuk kontraktor?', 'qualified', 'website', encode(sha256(convert_to('fransiska.ayu@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-06-23 14:40+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000010', 'PT Kapuas Lestari', 'procurement@example.com', null, 'masterplan', 'Di atas Rp1 M', 'Kami membutuhkan masterplan untuk kawasan guest house dan restoran di tepi Sungai Kapuas, luas lahan sekitar 1,2 ha. Mohon kirimkan company profile.', 'contacted', 'website', encode(sha256(convert_to('procurement@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-07-30 09:05+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000011', 'Steven Tan', 'steven.tan88@example.com', null, 'commercial', 'Rp250 – 500 jt', 'Mau konsultasi desain roastery sekaligus coffee bar, bangunan eksisting gudang 12 x 24 m. Kapan bisa survei?', 'qualified', 'website', encode(sha256(convert_to('steven.tan88@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-08-18 20:10+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000012', 'Nurul Fadilah', 'nurul.fadilah@example.com', null, 'residential', 'Rp100 – 250 jt', 'Rumah tipe 70 di perumahan, ingin tambah lantai 2 untuk kamar anak. Apakah perlu perhitungan struktur ulang? Terima kasih.', 'closed', 'website', encode(sha256(convert_to('nurul.fadilah@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-09-02 10:30+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000013', 'Andre Kurniawan', 'andre.kurniawan@example.com', null, 'commercial', 'Rp250 – 500 jt', 'Kami berencana membuka kedai kopi dengan konsep semi-outdoor di Jl. Ahmad Yani. Lahan sudah ada, butuh desain dan estimasi biaya. Bisa dibantu minggu depan?', 'new', 'website', encode(sha256(convert_to('andre.kurniawan@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-09-29 15:42+07');
insert into public.inquiries (id, name, email, phone, project_type, budget_range, message, status, source, ip_hash, user_agent, created_at) values ('c0de0007-0000-4000-8000-000000000014', 'Lestari Wulandari', 'lestari.wulan@example.com', null, 'residential', 'Rp500 jt – Rp1 M', 'Halo, saya berencana membangun rumah dua lantai di Sungai Raya, luas tanah 12 x 25 m. Kami ingin rumah yang sejuk tanpa terlalu bergantung pada AC. Apakah bisa dari konsep sampai gambar kerja?', 'new', 'website', encode(sha256(convert_to('lestari.wulan@example.com', 'UTF8')), 'hex'), 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1', '2026-09-30 21:03+07');
